  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100000) return 'arr needs 1 to 10^5 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value of arr is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 0 || k > arr.length) return 'k is an integer from 0 to arr.length.';
  return null;
}

