function findLeastNumOfUniqueInts(arr, k) {
  const count = new Map();
  for (const value of arr) {
    count.set(value, (count.get(value) ?? 0) + 1);
  }

  const frequencies = [...count.values()].sort((a, b) => a - b);
  let remaining = frequencies.length;

  for (const frequency of frequencies) {
    if (frequency > k) {
      break;
    }
    k -= frequency;
    remaining--;
  }
  return remaining;
}

