function findLeastNumOfUniqueInts(arr, k) {
  // 0/1 knapsack: most[j] is the largest number of distinct values that can be wiped out
  // completely using at most j deletions.
  const distinct = [...new Set(arr)];
  const sizes = distinct.map(v => arr.filter(x => x === v).length);
  const most = new Array(k + 1).fill(0);
  for (const s of sizes)
    for (let j = k; j >= s; j--) most[j] = Math.max(most[j], most[j - s] + 1);
  return distinct.length - most[k];
}

