function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const length = pick(1500, 2000);
    const poolSize = rand() < 0.5 ? pick(20, 200) : pick(500, 1500);
    const pool = Array.from({ length: poolSize }, () => pick(1, 1000000000));
    // Skewing the choice gives some values many copies and others only one or two.
    const arr = Array.from({ length }, () => pool[Math.floor(Math.pow(rand(), 2) * poolSize)]);
    const k = rand() < 0.15 ? (rand() < 0.5 ? 0 : length) : pick(0, length);
    return [arr, k];
  }
  const length = pick(1, 10);
  const span = pick(1, 6);
  const big = rand() < 0.3;
  const arr = Array.from({ length }, () => (big ? 1000000000 - pick(0, span - 1) : pick(1, span)));
  const k = pick(0, length);
  return [arr, k];
}
